mapper.select:
select
id,role_id,entity_id,ref_type,resource_id,storage_provilege,repository_privilege,path_privilege,create_by,create_time
from role_resource_ref


        and id = #{id}


        and role_id = #{roleId}


        and entity_id = #{entityId}


        and ref_type = #{refType}


        and resource_id = #{resourceId}


        and storage_provilege = #{storageProvilege}


        and repository_privilege = #{repositoryPrivilege}


        and path_privilege = #{pathPrivilege}


        and create_by = #{createBy}


        and create_time = #{createTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from role_resource_ref


        and id = #{id}


        and role_id = #{roleId}


        and entity_id = #{entityId}


        and ref_type = #{refType}


        and resource_id = #{resourceId}


        and storage_provilege = #{storageProvilege}


        and repository_privilege = #{repositoryPrivilege}


        and path_privilege = #{pathPrivilege}


        and create_by = #{createBy}


        and create_time = #{createTime}

select fr.*, GROUP_CONCAT(distinct rrr.storage_provilege) AS storageProvilege, GROUP_CONCAT(distinct rrr.repository_privilege) AS repositoryPrivilege, GROUP_CONCAT(distinct rrr.path_privilege) AS pathPrivilege from folib_user fu left join (select rrr1.role_id, rrr1.storage_provilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id as user_id from role_resource_ref rrr1 where rrr1.ref_type = 1 union all select rrr2.role_id, rrr2.storage_provilege, rrr2.repository_privilege, rrr2.path_privilege, ugr.user_id as user_id from user_group_ref ugr join role_resource_ref rrr2 on ugr.user_group_id = rrr2.entity_id where rrr2.ref_type = 2 ) rrr rrr on fu.id = rrr.user_id left join folib_role fr on fu.id = rrr.user_id and fr.id = rrr.role_id where fr.deleted = "0"
and fu.id = #{username}
group by fr.id limit #{pageable.offset}, #{pageable.pageSize}
